-- Catálogo global de ejercicios organizado por categoría (28 categorías).
-- Los 3 ejercicios (DEMO) ya existentes se REUTILIZAN: se renombran y
-- categorizan en lugar de insertarse duplicados (ver UPDATE al inicio).
-- Todo lo demás se inserta como ejercicio global (gym_id NULL), disponible
-- para todos los gimnasios y protegido contra edición/desactivación desde
-- cualquier gimnasio individual (la aplicación ya impone esto mediante
-- WHERE gym_id = $gymId en updateExercise/setExerciseStatus).

ALTER TABLE exercises ADD COLUMN category TEXT;
CREATE INDEX idx_exercises_gym_category ON exercises (gym_id, category);

-- Reutilización de ejercicios existentes (no se duplican)
UPDATE exercises SET name = 'Press de banca plano con barra', category = 'Pecho', muscle_group = 'CHEST', exercise_type = 'STRENGTH', equipment = 'Barra', updated_at = datetime('now') WHERE id = 'exercise_demo_001';
UPDATE exercises SET name = 'Peso muerto convencional', category = 'Espalda', muscle_group = 'BACK', exercise_type = 'STRENGTH', equipment = 'Barra', updated_at = datetime('now') WHERE id = 'exercise_demo_003';
UPDATE exercises SET name = 'Sentadilla trasera', category = 'Cuádriceps', muscle_group = 'QUADRICEPS', exercise_type = 'STRENGTH', equipment = 'Barra', updated_at = datetime('now') WHERE id = 'exercise_demo_002';

